// Store screenshots, captured by driving the real app rather than mocking it.
// Generated by .sweep/capture_screenshots.py - regenerate rather than hand-edit.
//
// A screenshot only lands if that screen actually rendered, so this doubles as
// proof the app launches and its primary destinations build.
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';
import 'package:pilot_enroute/main.dart' as app;

void main() {
  final binding = IntegrationTestWidgetsFlutterBinding.ensureInitialized();

  Future<void> shoot(WidgetTester tester, String name) async {
    // pumpAndSettle throws if something animates forever (shimmer, spinner),
    // which must not lose the screenshot - fall back to a fixed pump.
    try {
      await tester.pumpAndSettle(const Duration(milliseconds: 500));
    } on Exception {
      await tester.pump(const Duration(seconds: 2));
    }
    await binding.takeScreenshot(name);
  }

  testWidgets('store screenshots', (WidgetTester tester) async {
    app.main();
    try {
      await tester.pumpAndSettle(const Duration(seconds: 5));
    } on Exception {
      await tester.pump(const Duration(seconds: 3));
    }
    await shoot(tester, '01_home');

    // Walk whichever primary navigation this app uses.
    var shot = 1;
    Future<void> tapThrough(Iterable<Finder> targets) async {
      for (final Finder f in targets) {
        if (shot >= 6) return;
        if (f.evaluate().isEmpty) continue;
        try {
          await tester.tap(f, warnIfMissed: false);
        } on Exception {
          continue;
        }
        shot += 1;
        await shoot(tester, '0${shot}_screen$shot');
      }
    }

    // Several apps in this portfolio build their tab bar from bare
    // GestureDetectors, so none of the three standard finders match and only
    // the home screen is ever captured. Play requires at least two phone
    // screenshots, so fall back to scrolling the primary scrollable: a second
    // shot of genuinely different content, rather than a duplicate.
    Future<void> scrollFallback() async {
      if (shot >= 2) return;
      final scrollable = find.byType(Scrollable);
      if (scrollable.evaluate().isEmpty) return;
      for (final offset in [-600.0, -600.0]) {
        if (shot >= 3) return;
        try {
          await tester.drag(scrollable.first, Offset(0, offset));
          await tester.pumpAndSettle(const Duration(milliseconds: 400));
        } on Exception {
          return;
        }
        shot += 1;
        await shoot(tester, '0${shot}_screen$shot');
      }
    }

    final navBar = find.byType(NavigationBar);
    final bottomBar = find.byType(BottomNavigationBar);
    final tabBar = find.byType(TabBar);

    if (navBar.evaluate().isNotEmpty) {
      final NavigationBar nav = tester.widget<NavigationBar>(navBar.first);
      await tapThrough([
        for (int i = 1; i < nav.destinations.length; i++)
          find.byWidget(nav.destinations[i]),
      ]);
    } else if (bottomBar.evaluate().isNotEmpty) {
      final BottomNavigationBar bar =
          tester.widget<BottomNavigationBar>(bottomBar.first);
      await tapThrough([
        for (int i = 1; i < bar.items.length; i++)
          if (bar.items[i].label != null)
            find.text(bar.items[i].label!).hitTestable()
          else
            find.byIcon((bar.items[i].icon as Icon).icon!).hitTestable(),
      ]);
    } else if (tabBar.evaluate().isNotEmpty) {
      final TabBar bar = tester.widget<TabBar>(tabBar.first);
      await tapThrough([
        for (int i = 1; i < bar.tabs.length; i++) find.byWidget(bar.tabs[i]),
      ]);
    }

    await scrollFallback();
  });
}
